import { useState, useRef, useEffect } from 'react';
import { FFmpeg } from '@ffmpeg/ffmpeg';
import { toBlobURL, fetchFile } from '@ffmpeg/util';

export function useFFmpeg() {
    const [loaded, setLoaded] = useState(false);
    const [progress, setProgress] = useState(0);
    const ffmpegRef = useRef(new FFmpeg());
    const messageRef = useRef<HTMLParagraphElement | null>(null);

    const load = async () => {
        const baseURL = 'https://unpkg.com/@ffmpeg/core@0.12.6/dist/umd';
        const ffmpeg = ffmpegRef.current;

        ffmpeg.on('log', ({ message }) => {
            console.log(message);
            if (messageRef.current) messageRef.current.innerHTML = message;
        });

        ffmpeg.on('progress', ({ progress }) => {
            setProgress(progress);
        });

        await ffmpeg.load({
            coreURL: await toBlobURL(`${baseURL}/ffmpeg-core.js`, 'text/javascript'),
            wasmURL: await toBlobURL(`${baseURL}/ffmpeg-core.wasm`, 'application/wasm'),
        });

        setLoaded(true);
    };

    const processFusion = async (audioFile: File, videoFiles: File[]) => {
        if (!loaded) await load();
        const ffmpeg = ffmpegRef.current;

        // 1. Write Audio File
        await ffmpeg.writeFile('audio.mp3', await fetchFile(audioFile));

        // 2. Write Video Files & Create Concat List
        let concatContent = '';
        for (let i = 0; i < videoFiles.length; i++) {
            const fileName = `video${i}.mp4`;
            await ffmpeg.writeFile(fileName, await fetchFile(videoFiles[i]));
            concatContent += `file '${fileName}'\n`;
        }
        await ffmpeg.writeFile('concat_list.txt', concatContent);

        // 3. Concatenate Videos into one intermediate file
        // We use -stream_loop -1 before the input to loop it infinitely
        // But we can't easily loop a concat list directly in one go with -stream_loop
        // So we first concat them into a single stream, then loop that stream.
        // Actually, a better approach for "looping a sequence" is to concat them first to a temporary file
        // OR use the concat demuxer with a loop.

        // Let's try a simpler approach: 
        // 1. Concat all videos into 'combined_video.mp4'
        // 2. Loop 'combined_video.mp4' and cut at audio duration.

        await ffmpeg.exec([
            '-f', 'concat',
            '-safe', '0',
            '-i', 'concat_list.txt',
            '-c', 'copy',
            'combined.mp4'
        ]);

        // 4. Final Fusion
        // -stream_loop -1: Loop the video input infinitely
        // -i combined.mp4: The video input
        // -i audio.mp3: The audio input
        // -map 0:v: Use video from first input
        // -map 1:a: Use audio from second input
        // -shortest: Stop when the shortest stream ends (which should be audio, since video is looped)
        // -c:v libx264: Re-encode video to ensure compatibility (and handle looping correctly)
        // -preset ultrafast: For speed
        // -c:a copy: Copy audio without re-encoding

        await ffmpeg.exec([
            '-stream_loop', '-1',
            '-i', 'combined.mp4',
            '-i', 'audio.mp3',
            '-map', '0:v',
            '-map', '1:a',
            '-c:v', 'libx264',
            '-preset', 'ultrafast',
            '-c:a', 'copy',
            '-shortest',
            'output.mp4'
        ]);

        // 5. Read Output
        const data = await ffmpeg.readFile('output.mp4');
        const blobData = data instanceof Uint8Array ? data.buffer : data;
        return new Blob([blobData as any], { type: 'video/mp4' });
    };

    return { loaded, load, processFusion, progress };
}
